<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted,shallowRef,watch} from 'vue';
import {defaults,validate,duplicateTarget} from './model';
import type {Round,Config} from './model';
import {Engine} from './engine';
import {SETTINGS,SESSION,OBSERVED,readStored,writeStored,packEngine,unpackEngine,mergeRounds,stoppedSnapshot} from './persistence';
import {gapMatrix,stripColor} from './statistics';
import {multiplier} from './adapter';
import {telegramDefaults,validateTelegram} from './signals';
import type {Signal} from './signals';
const telegram=ref(telegramDefaults());const signalLogs=ref<Signal[]>([]);const signalTargets=ref('90;250;450');
const hasExtension=typeof chrome!=='undefined'&&!!chrome.runtime?.id;
const signalPage=location.hash==='#signals';
const eventLabels={hit:'Big hit',entry:'Đủ chuỗi',win:'Thắng',loss:'Thua',step:'Tăng bậc',error:'Lỗi / mất kết nối',startStop:'Bắt đầu / dừng',round:'Trạng thái mỗi vòng'};
async function loadTelegram(){if(!hasExtension)return;try{const r=await chrome.runtime.sendMessage({type:'telegram-get'});if(r.config){telegram.value=r.config;signalTargets.value=r.config.rules.targets.join(';')}signalLogs.value=r.logs||[]}catch{notice.value='Không đọc được cấu hình Telegram'}}
async function saveTelegram(){try{if(!hasExtension)throw Error('Cài extension để dùng Telegram');telegram.value.token=telegram.value.token.trim();telegram.value.chatId=telegram.value.chatId.trim();telegram.value.rules.targets=signalTargets.value.split(/[;\s]+/).filter(Boolean).map(Number);validateTelegram(telegram.value);if(telegram.value.enabled&&!await chrome.permissions.request({origins:['https://api.telegram.org/*']}))throw Error('Chưa cấp quyền kết nối Telegram');const r=await chrome.runtime.sendMessage({type:'telegram-save',config:JSON.parse(JSON.stringify(telegram.value))});if(!r.ok)throw Error(r.error);notice.value='Đã lưu Telegram'}catch(e){notice.value=String(e)}}
async function testTelegram(){if(!hasExtension)return;notice.value='Đang gửi tin thử…';const r=await chrome.runtime.sendMessage({type:'telegram-test'});notice.value=r.ok?'Đã gửi tin thử Telegram':r.error||'Không gửi được';await loadTelegram()}
function storageChange(changes:Record<string,chrome.storage.StorageChange>){if(changes['slide-signals-v1'])signalLogs.value=changes['slide-signals-v1'].newValue||[]}
function openSignals(){if(hasExtension)void chrome.runtime.sendMessage({type:'open-signals'})}
const liveState=ref<any>(null);const liveOptions=ref({currency:'usdt',maxRoundBet:0.01,maxTotalBet:0,maxRounds:0,continuous:true,balanceSelector:''});
const locked=computed(()=>running.value||liveState.value?.running===true);
function adjustStep(id:string,delta:number){window.parent.postMessage({channel:'slide-lab',type:'adjust-step',id,delta},'*')}
function liveCommand(type:string){if(type==='start-live'){try{validate(config.value);if(!embedded)throw Error('Auto chỉ chạy trong extension trên trang Stake');if(running.value)throw Error('Dừng mô phỏng trước khi chạy Auto');if(!liveOptions.value.balanceSelector.trim())throw Error('Chọn số dư trên trang trước khi chạy Auto');const plans=new Engine(JSON.parse(JSON.stringify(config.value)),rounds.value).next();const total=plans.filter(p=>p.action==='BET').reduce((a,p)=>a+p.amount,0);if(liveOptions.value.maxRoundBet>0&&total>liveOptions.value.maxRoundBet)throw Error(`Tổng mức vòng đầu ${money(total)} vượt giới hạn/vòng ${money(liveOptions.value.maxRoundBet)}; kiểm tra các bảng đang bật`);if(!config.value.targets.some(t=>t.enabled))throw Error('Kích hoạt ít nhất một target');window.parent.postMessage({channel:'slide-lab',type,config:JSON.parse(JSON.stringify(config.value)),options:JSON.parse(JSON.stringify(liveOptions.value))},'*')}catch(e){notice.value=String(e)}}else window.parent.postMessage({channel:'slide-lab',type},'*')}
const editorOpen=ref(true);
const config=ref<Config>(defaults());const tab=ref(signalPage?'Telegram':'Cược');const selected=ref('450');
const engine=shallowRef<Engine|null>(null);const revision=ref(0);const running=ref(false);const rounds=ref<Round[]>([]);
const connected=ref(false);const status=ref('Mở Slide rồi bấm biểu tượng extension');const notice=ref('');
const backtext=ref('1.45\n9.54\n4.09\n1.30\n2.02\n1.50\n1.04\n1.00\n2.23');const report=shallowRef<Engine|null>(null);const manual=ref('2.23');
const embedded=window.parent!==window;const target=computed(()=>config.value.targets.find(t=>t.id===selected.value)||config.value.targets[0]);
const stats=computed(()=>{revision.value;return engine.value});const next=computed(()=>{revision.value;return engine.value?.next()||[]});
const logs=computed(()=>{revision.value;return engine.value?.trades.slice(-100).reverse()||[]});
const statWindow=ref(0);const minHit=ref(90);const newThreshold=ref(100);const thresholds=ref([2,3,5,10,20,35,50,75,90,150,250,370,410,450,680,880,1880,3200,6000,8900]);
const statRounds=computed(()=>statWindow.value?rounds.value.slice(-statWindow.value):rounds.value);const matrix=computed(()=>gapMatrix(statRounds.value,thresholds.value));const bigHits=computed(()=>statRounds.value.filter(r=>r.value>=minHit.value).slice(-100).reverse());
const plannedTotal=computed(()=>{try{const plans=liveState.value?.next||new Engine(JSON.parse(JSON.stringify(config.value)),rounds.value).next();return plans.filter((p:any)=>p.action==='BET').reduce((sum:number,p:any)=>sum+p.amount,0)}catch{return null}});
const statsSource=ref('Auto');const sessionStats=computed(()=>statsSource.value==='Auto'?liveState.value:stats.value);const sessionTargets=computed(()=>statsSource.value==='Auto'?liveState.value?.targets||[]:engine.value?.config.targets||[]);
function addThreshold(){const n=newThreshold.value;if(Number.isFinite(n)&&n>=1&&!thresholds.value.includes(n))thresholds.value=[...thresholds.value,n].sort((a,b)=>a-b)}
function wide(){window.parent.postMessage({channel:'slide-lab',type:'wide'},'*')}
const money=(n:number)=>n.toLocaleString('en-US',{maximumFractionDigits:8});
async function save(){try{validate(config.value);if(liveState.value?.running&&config.value.bankroll!==liveState.value.bankroll)throw Error('Vốn khởi tạo chỉ đổi khi bắt đầu phiên mới');await persistSettings();if(liveState.value?.running){window.parent.postMessage({channel:'slide-lab',type:'update-config',config:JSON.parse(JSON.stringify(config.value))},'*');notice.value='Đang gửi chiến thuật mới; chờ áp dụng sau ván đang cược'}else notice.value='Đã lưu cấu hình'}catch(e){notice.value=String(e)}}
function start(){try{if(liveState.value?.running)throw Error('Dừng Auto trước khi chạy mô phỏng');validate(config.value);if(!config.value.targets.some(t=>t.enabled))throw Error('Kích hoạt ít nhất một target');if(embedded&&!connected.value)throw Error('Chưa có dữ liệu vòng ổn định');engine.value=new Engine(JSON.parse(JSON.stringify(config.value)),rounds.value);running.value=true;status.value='Đang mô phỏng';revision.value++}catch(e){notice.value=String(e)}}
function stop(reason='Đã dừng mô phỏng'){running.value=false;status.value=reason}
function accept(batch:Round[]){for(const r of batch){if(rounds.value.some(old=>old.id===r.id))continue;if(running.value&&engine.value){try{engine.value.consume(r);revision.value++;if(engine.value.halted)stop(engine.value.halted)}catch(e){stop('Lỗi dữ liệu');notice.value=String(e)}}rounds.value.push(r);rounds.value=rounds.value.slice(-5000)}}
function receive(e:MessageEvent){if(e.source!==window.parent||!['https://stake1022.com','https://www.stake1022.com'].includes(e.origin)||e.data?.channel!=='slide-lab')return;const {type,data}=e.data;
 if(['seed','gap','rounds'].includes(type)){if(!Array.isArray(data)||data.length>5000||!data.every(r=>r&&typeof r.id==='string'&&Number.isFinite(r.value)&&r.value>=1&&Number.isFinite(r.time)))return;if(type==='rounds')accept(data);else{rounds.value=mergeRounds(rounds.value,data);if(type==='gap')stop('Gián đoạn dữ liệu — bấm bắt đầu để tạo phiên mới')}}
 if(type==='diagnostics'){download('slide-diagnostics.json',JSON.stringify(data,null,2));notice.value='Đã xuất slide-diagnostics.json (không chứa token/cookie)';return}
 if(type==='balance-picked'){liveOptions.value.balanceSelector=data.selector;notice.value=`Đã chọn số dư: ${data.text}`;return}
 if(type==='picker-status'){notice.value=data;return}
 if(type==='live-state'){if(data?.running&&!liveState.value?.running)editorOpen.value=false;liveState.value=data;return}
 if(type==='status'){connected.value=data?.ok===true;if(!connected.value&&running.value)stop('Nguồn dữ liệu gián đoạn hoặc quá 45 giây chưa có vòng mới')}
}
function close(){window.parent.postMessage({channel:'slide-lab',type:'close'},'*')}
function copyTarget(){if(running.value)return;if(config.value.targets.length>=20){notice.value='Tối đa 20 bảng';return}const t=duplicateTarget(target.value,crypto.randomUUID());config.value.targets.push(t);selected.value=t.id;notice.value='Đã nhân đôi bảng (chưa kích hoạt). Chỉnh target rồi bật và Lưu.'}
function addTarget(){if(config.value.targets.length>=20){notice.value='Tối đa 20 bảng';return}const t=structuredClone(defaults().targets[0]);t.id=crypto.randomUUID();t.target=2;t.enabled=false;config.value.targets.push(t);selected.value=t.id}
function removeTarget(){if(config.value.targets.length===1)return;config.value.targets=config.value.targets.filter(t=>t.id!==target.value.id);selected.value=config.value.targets[0].id}
function download(name:string,content:string,type='application/json'){const u=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
async function importConfig(e:Event){try{const f=(e.target as HTMLInputElement).files?.[0];if(!f)return;if(f.size>1e6)throw Error('File quá lớn');const c=JSON.parse(await f.text());validate(c);config.value=c;selected.value=c.targets[0].id;save()}catch(e){notice.value=String(e)}}
function parseHistory(text:string):Round[]{
 const clean=text.trim();if(!clean)throw Error('Chưa có dữ liệu');let data:unknown[];
 if(clean.startsWith('[')){data=JSON.parse(clean);if(!Array.isArray(data))throw Error('JSON cần là mảng')}else data=clean.split(/\r?\n/).filter(s=>s.trim()&&!/^multiplier$/i.test(s.trim()));
 if(data.length>100000)throw Error('Tối đa 100.000 vòng');const ids=new Set<string>();return data.map((x:any,i)=>{const v=typeof x==='object'&&x!==null?x.value:typeof x==='number'?x:multiplier(String(x));const id=typeof x==='object'&&x?.id?String(x.id):`import-${i}`;if(!Number.isFinite(v)||v<1||ids.has(id))throw Error(`Dòng ${i+1}: hệ số không hợp lệ hoặc ID trùng`);ids.add(id);return {id,value:v,time:Number.isFinite(x?.time)?x.time:i}});
}
function backtest(){try{const rs=parseHistory(backtext.value);const en=new Engine(JSON.parse(JSON.stringify(config.value)));for(const r of rs){en.consume(r);if(en.halted)break}report.value=en;notice.value=`Đã xử lý ${en.count}/${rs.length} vòng${en.halted?' • '+en.halted:''}`}catch(e){notice.value=String(e)}}
async function importHistory(e:Event){const f=(e.target as HTMLInputElement).files?.[0];if(!f)return;if(f.size>15e6){notice.value='File quá lớn';return}backtext.value=await f.text()}
function addManual(){const v=multiplier(manual.value);if(!Number.isFinite(v)||v<1){notice.value='Hệ số phải ≥ 1';return}accept([{id:crypto.randomUUID(),value:v,time:Date.now()}])}
function useObserved(){backtext.value=JSON.stringify(rounds.value);tab.value='Backtest'}
function csv(){const rows=engine.value?.trades||[];download('slide-paper-trades.csv','round_id,time,result,target,step,amount,outcome,profit\n'+rows.map(r=>[r.roundId,r.time,r.result,r.target,r.step,r.amount,r.outcome,r.profit].join(',')).join('\n'),'text/csv')}
const spark=computed(()=>{if(!report.value?.trades.length)return '';let equity=0;const series=[0,...report.value.trades.map(t=>equity+=t.profit)];const min=Math.min(...series),max=Math.max(...series);return series.filter((_,i)=>i%Math.max(1,Math.floor(series.length/200))===0||i===series.length-1).map((v,i,a)=>`${i/(a.length-1||1)*600},${100-(v-min)/(max-min||1)*85}`).join(' ')});
let hydrated=false;let writeQueue=Promise.resolve();
function store(key:string,data:unknown){data=JSON.parse(JSON.stringify(data));writeQueue=writeQueue.catch(()=>{}).then(()=>writeStored(key,data));return writeQueue}
function persistSettings(){return store(SETTINGS,{config:config.value,liveOptions:liveOptions.value,selected:selected.value,thresholds:thresholds.value,statWindow:statWindow.value,minHit:minHit.value,backtext:backtext.value,manual:manual.value,statsSource:statsSource.value})}
function persistSession(){return store(SESSION,{engine:packEngine(engine.value),report:packEngine(report.value),rounds:rounds.value})}
watch([config,liveOptions,selected,thresholds,statWindow,minHit,backtext,manual,statsSource],()=>{if(hydrated)void persistSettings().catch(()=>{notice.value='Không lưu được cấu hình; kiểm tra dung lượng extension'})},{deep:true,flush:'sync'});
watch([revision,engine,report,rounds],()=>{if(hydrated)void persistSession().catch(()=>{notice.value='Không lưu được lịch sử phiên'})},{deep:true});
onMounted(async()=>{
 void loadTelegram();if(hasExtension)chrome.storage.onChanged.addListener(storageChange);
 try{
  const saved=await readStored(SETTINGS);
  if(saved){validate(saved.config);config.value=saved.config;liveOptions.value={...liveOptions.value,...saved.liveOptions};selected.value=saved.selected;thresholds.value=saved.thresholds??thresholds.value;statWindow.value=saved.statWindow??0;minHit.value=saved.minHit??90;backtext.value=saved.backtext??backtext.value;manual.value=saved.manual??manual.value;statsSource.value=saved.statsSource??'Auto'}
  else{const legacy=localStorage.getItem('slide-lab-config-v1');if(legacy){const c=JSON.parse(legacy);validate(c);config.value=c;selected.value=c.targets[0].id;await persistSettings()}}
  const session=await readStored(SESSION);if(session){engine.value=unpackEngine(session.engine);report.value=unpackEngine(session.report);rounds.value=session.rounds??[];revision.value++}
  const observed=await readStored(OBSERVED);if(observed){rounds.value=mergeRounds(rounds.value,observed.history??[]);liveState.value=stoppedSnapshot(observed.live)}
 }catch{notice.value='Không khôi phục được một phần dữ liệu đã lưu'}
 hydrated=true;window.addEventListener('message',receive);if(embedded)window.parent.postMessage({channel:'slide-lab',type:'ready'},'*');
});
onUnmounted(()=>{window.removeEventListener('message',receive);if(hasExtension)chrome.storage.onChanged.removeListener(storageChange)});
</script>

<template>
 <main :class="{compact:tab==='Cược'}">
  <header><div class="logo">S<span>↗</span></div><div><h1>Slide Lab <small>v1.0.10</small></h1></div><button v-if="embedded" class="icon diagnostic-button" title="Xuất chẩn đoán" aria-label="Xuất chẩn đoán" @click="liveCommand('diagnostics')">↧</button><button v-if="embedded" class="icon" @click="close" aria-label="Đóng">✕</button></header>
  <nav class="main-nav"><button :class="{active:tab==='Cược'}" @click="tab='Cược'">CƯỢC</button><button :class="{active:tab!=='Cược'}" @click="tab='Thống kê'">THỐNG KÊ / CÔNG CỤ</button></nav>
  <nav v-if="tab!=='Cược'" class="secondary-nav"><button v-for="name in ['Thống kê','Lịch sử','Auto Bet','Mô phỏng','Backtest','Telegram','Hướng dẫn']" :class="{active:tab===name}" @click="tab=name">{{name}}</button></nav>
  <section v-if="!signalPage && tab==='Mô phỏng'" class="control">
   <div class="row"><span><i :class="{online:connected}"/> {{ running?'Đang mô phỏng':status }}</span><span class="badge">PAPER ONLY</span></div>
   <button class="primary" @click="running?stop():start()">{{ running?'■ DỪNG MÔ PHỎNG':'▶ BẮT ĐẦU PHIÊN MÔ PHỎNG' }}</button>
   <div class="metrics"><div><label>Vốn giả lập</label><b>{{ money(stats?.balance ?? config.bankroll) }}</b></div><div><label>Lãi / lỗ</label><b :class="(stats?.profit||0)<0?'negative':'positive'">{{ money(stats?.profit||0) }}</b></div><div><label>Vòng phiên này</label><b>{{ stats?.count||0 }}</b></div></div>
   <p class="fine">Chỉ tính trên vòng mới sau khi bắt đầu. Tất cả số tiền ở đây là số liệu mô phỏng.</p>
  </section>
  <section v-if="!signalPage && tab!=='Mô phỏng'" class="control real-control">
   <div class="row live-toolbar"><span><i :class="{online:liveState?.running}"/> {{liveState?.running?'AUTO ĐANG CHẠY':'AUTO ĐÃ DỪNG'}}</span><button v-if="liveState?.running" class="primary" @click="liveCommand('stop-live')">■ DỪNG</button><button v-else-if="tab==='Cược'" class="primary" :disabled="!embedded||running" @click="liveCommand('start-live')">▶ CƯỢC THẬT</button></div>
   <div class="metrics"><div><label>Số dư trang</label><b>{{liveState?.wallet==null?'Chưa đọc':money(liveState.wallet)}}</b></div><div><label>P/L tính</label><b :class="(liveState?.profit||0)<0?'negative':'positive'">{{liveState?money(liveState.profit||0):'—'}}</b></div><div><label>Vòng cược</label><b>{{liveState?.betRounds||0}}</b></div></div>
   <p class="live-reason">{{liveState?.message||'Chọn số dư và chỉnh bảng trong Cấu hình bên dưới.'}}</p>
   <p class="fine" v-if="running">Mô phỏng đang chạy riêng. <button @click="stop()">Dừng mô phỏng</button></p>
  </section>
  <div v-if="notice" class="notice" role="status">{{ notice }} <button class="icon" @click="notice=''">✕</button></div>
  <template v-if="tab==='Cược'">
   <section class="live-progress"><h3>TIẾN ĐỘ LIVE</h3><p v-if="!liveState?.progress?.length" class="fine">{{config.targets.filter(t=>t.enabled).map(t=>t.target+'×').join(' · ')||'Chưa bật bảng'}} · chưa có phiên.</p><article class="progress-card" v-for="p in (liveState?.progress||[]).filter((p:any)=>p.enabled)"><div class="row"><b>x{{money(p.target)}} <small>Bậc {{p.step}}/{{p.steps}}</small> <button class="step-button" aria-label="Giảm bậc" :disabled="!liveState.running||liveState.busy||(p.queuedStep??p.step)<=1" @click="adjustStep(p.id,-1)">−</button><button class="step-button" aria-label="Tăng bậc" :disabled="!liveState.running||liveState.busy||(p.queuedStep??p.step)>=p.steps" @click="adjustStep(p.id,1)">＋</button></b><span :class="p.profit<0?'negative':'positive'">P/L {{money(p.profit)}} <small :class="p.outcome==='LOSS'?'negative':'positive'">{{p.outcome}}</small></span></div><div class="row"><span class="progress-bet-estimate">{{money(p.amount)}} · x{{money(p.actualTarget)}}<small class="win-profit-estimate" title="Lãi ròng riêng cược này nếu thắng, đã trừ tiền cược; chưa cộng/trừ P/L trước đó">Lãi nếu thắng: +{{money(p.action==='WAIT'?0:Number((p.amount*(p.actualTarget-1)).toFixed(8)))}}</small></span><span>Bậc {{p.step}}: {{p.used}}/{{p.limit}}v · W{{p.wins}} L{{p.losses}}</span></div><progress :value="p.used" :max="p.limit"></progress><p class="fine">Đã cược {{p.wins+p.losses}}v · {{p.queuedStep?'Chờ đổi → bậc '+p.queuedStep:p.reason}}</p></article></section>
   <details class="strategy-editor" :open="editorOpen" @toggle="editorOpen=($event.target as HTMLDetailsElement).open"><summary>CẤU HÌNH CHIẾN THUẬT <span>{{config.targets.filter(t=>t.enabled).length}} bảng bật · trần/vòng {{liveOptions.maxRoundBet===0?'tắt':money(liveOptions.maxRoundBet)}}</span></summary>
   <fieldset :disabled="locked"><section class="quick-settings"><div class="row"><label>Đồng cược<input v-model="liveOptions.currency" placeholder="usdt"></label><button :disabled="!embedded" @click="liveCommand('pick-balance')">Chọn số dư trên Stake</button></div><p class="fine">Bấm Chọn số dư rồi bấm con số ví ở đầu trang. 3 vòng có cược mà số dư đứng yên → dừng để kiểm tra.</p><label class="visible-cap">Trần tổng cược / vòng · 0 = tắt<input type="number" min="0" step="0.001" v-model.number="liveOptions.maxRoundBet"></label><p class="planned-total" :class="plannedTotal!==null&&liveOptions.maxRoundBet>0&&plannedTotal>liveOptions.maxRoundBet?'negative':''">Tổng vòng tới: {{plannedTotal===null?'—':money(plannedTotal)}} {{plannedTotal!==null&&liveOptions.maxRoundBet>0&&plannedTotal>liveOptions.maxRoundBet?'· VƯỢT TRẦN':''}}</p><details><summary>Giới hạn phiên · 0 = không giới hạn</summary><div class="grid2"><label>Tổng tiền đặt phiên<input type="number" min="0" step="0.001" v-model.number="liveOptions.maxTotalBet"></label><label>Tối đa lượt<input type="number" min="0" step="1" v-model.number="liveOptions.maxRounds"></label></div><label class="check"><input type="checkbox" v-model="liveOptions.continuous"> Giữ Auto · Số Cược = 0 khi mức / target không đổi</label></details></section></fieldset>
   <fieldset :disabled="running">
    <p class="fine" v-if="liveState?.running">Sửa bảng rồi bấm Lưu; áp dụng sau ván đang cược. {{liveState.configUpdatePending?'Đang chờ áp dụng.':''}}</p>
    <div class="row section-title"><h2>Bảng cược</h2><div class="row"><button class="accent" @click="save">Lưu</button><button @click="addTarget">＋ Target</button></div></div>
    <div class="targets"><button v-for="t in config.targets" :class="{chosen:target.id===t.id}" @click="selected=t.id"><i :class="{online:t.enabled}"/>{{ t.target }}×</button></div>
    <section><div class="row"><label class="grow">Target (×)<input type="number" min="1.01" max="4294967000" step="0.01" v-model.number="target.target"></label><label class="check"><input type="checkbox" v-model="target.enabled"> Kích hoạt</label><button @click="copyTarget" aria-label="Nhân đôi bảng">Nhân đôi</button><button class="danger" @click="removeTarget">Xóa</button></div>
     <div class="entry"><label class="check"><input type="checkbox" v-model="target.entry.enabled"> Điều kiện vào chuỗi</label><div v-if="target.entry.enabled" class="grid3"><label>Số vòng<input type="number" min="1" step="1" v-model.number="target.entry.count"></label><label>Điều kiện<select v-model="target.entry.op"><option>&lt;</option><option>&gt;</option><option>&lt;=</option><option>&gt;=</option></select></label><label>Mốc (×)<input type="number" min="1" step="0.01" v-model.number="target.entry.value"></label></div></div>
     <div class="table-scroll"><table><thead><tr><th>Bậc</th><th>Mức</th><th>Target ×</th><th>Số vòng</th><th>Action</th><th></th></tr></thead><tbody><tr v-for="(s,i) in target.steps"><td>{{ i+1 }}</td><td><input aria-label="Mức cược" type="number" min="0.00000001" step="0.001" v-model.number="s.amount"></td><td><input aria-label="Target tại bậc" type="number" min="1.01" max="4294967000" step="0.01" :placeholder="String(target.target)" :value="s.multiplier??''" @input="s.multiplier=($event.target as HTMLInputElement).value===''?undefined:Number(($event.target as HTMLInputElement).value)"></td><td><input aria-label="Số vòng tại bậc" type="number" min="1" step="1" v-model.number="s.rounds"></td><td><select aria-label="Action" v-model="s.action"><option value="BET">Cược</option><option value="WAIT">Chờ</option></select></td><td><button class="icon danger" @click="target.steps.length>1&&target.steps.splice(i,1)" aria-label="Xóa bậc">×</button></td></tr></tbody></table></div>
     <button class="wide" @click="target.steps.push({amount:0.01,multiplier:target.target,rounds:100,action:'BET'})">＋ Thêm bậc</button>
    </section>
    <details><summary>Luật & ngân sách phiên</summary><section><label>Khi thua hết bảng<select v-model="config.exhausted"><option value="stop">Dừng target</option><option value="hold">Duy trì bậc cao nhất</option><option value="reset">Về bậc 1, chờ điều kiện</option></select></label><div class="grid3"><label>Ngân sách phiên / vốn mô phỏng<input type="number" min="0.01" :disabled="liveState?.running" v-model.number="config.bankroll"></label><label>Stop loss<input type="number" min="0" v-model.number="config.stopLoss"></label><label>Take profit<input type="number" min="0" v-model.number="config.takeProfit"></label></div><p class="fine">0 = tắt giới hạn. Giới hạn được kiểm tra sau khi tính xong một vòng; khoản lỗ có thể vượt mức giới hạn.</p><div class="row"><button class="accent" @click="save">Lưu cấu hình</button><button @click="download('slide-config.json',JSON.stringify(config,null,2))">Xuất JSON</button><label class="file-button">Nhập JSON<input type="file" accept=".json" @change="importConfig"></label></div></section></details>
   </fieldset>
   </details>
  </template>
  <template v-else-if="tab==='Auto Bet'">
   <section><h2>Auto Bet · bản thử nghiệm</h2><p>Tool điều khiển cược thật trên trang đang đăng nhập. Giữ Stake Auto chạy qua nhiều vòng khi mức và target chưa đổi. Khi đổi bậc làm thay đổi danh sách cược, tool dừng để xóa rồi thêm lại. Giữ Auto dùng Số Cược = 0 trên Stake. Tool vẫn dừng theo ngân sách, luật và các giới hạn lớn hơn 0 bạn nhập.</p><p class="fine">Bộ đọc DOM đã đối chiếu với trang. Phần đặt cược thật chưa được kiểm thử bằng tiền thật. Thống kê lãi/lỗ tính theo mức đã gửi và kết quả, không phải số dư ví được xác nhận từ API.</p></section>
   <fieldset :disabled="locked"><section><label class="check"><input type="checkbox" v-model="liveOptions.continuous"> Giữ Auto · Số Cược = 0 khi mức / target không đổi</label><label>Ô số dư trên trang<input v-model="liveOptions.balanceSelector" placeholder="Bấm Chọn số dư rồi bấm vào số tiền trên thanh đầu trang"></label><div class="row"><button :disabled="!embedded" @click="liveCommand('pick-balance')">Chọn số dư trên trang</button><button :disabled="!embedded" @click="liveCommand('check-live')">Kiểm tra lại</button></div><p class="fine">3 vòng có cược mà số dư không đổi → dừng Auto, kiểm tra mạng game / danh sách cược / ô số dư, rồi chờ bạn xử lý. Không tự cược lại khi trạng thái chưa rõ.</p><label>Đồng trên Stake (phải nhập theo đơn vị crypto)<input v-model="liveOptions.currency" placeholder="usdt"></label><div class="grid3"><label>Tổng cược tối đa / vòng<input type="number" min="0" step="0.001" v-model.number="liveOptions.maxRoundBet"></label><label>Tổng tiền đặt cả phiên<input type="number" min="0" step="0.001" v-model.number="liveOptions.maxTotalBet"></label><label>Tối đa lượt Auto<input type="number" min="0" step="1" v-model.number="liveOptions.maxRounds"></label></div><p>Chiến thuật dùng bảng trong màn hình Cược. Vốn ban đầu là ngân sách của phiên; số dư thực được đọc từ ô bạn chọn. Stop loss / take profit áp dụng cho lãi/lỗ tính toán của phiên.</p></section></fieldset>
   <button class="primary" :disabled="!embedded||running" @click="liveCommand(liveState?.running?'stop-live':'start-live')">{{liveState?.running?'■ DỪNG AUTO BET':'▶ BẮT ĐẦU AUTO BET THẬT'}}</button>
   <section v-if="liveState"><h3>{{liveState.message}}</h3><div class="metrics"><div><label>Vòng có cược</label><b>{{liveState.betRounds||0}}</b></div><div><label>Lãi/lỗ tính toán</label><b>{{money(liveState.profit||0)}}</b></div><div><label>Số dư đọc trang</label><b>{{liveState.wallet==null?'—':money(liveState.wallet)}}</b></div></div><div class="plan" v-for="p in liveState.next"><b>{{p.target}}×</b><span>Bậc {{p.step}}</span><strong>{{p.action==='WAIT'?'CHỜ':money(p.amount)}}</strong></div></section>
   <section class="table-scroll" v-if="liveState?.trades?.length"><table><thead><tr><th>Vòng ×</th><th>Target</th><th>Bậc</th><th>Mức</th><th>Kết quả</th></tr></thead><tbody><tr v-for="r in [...liveState.trades].reverse()"><td>{{r.result}}</td><td>{{r.target}}</td><td>{{r.step}}</td><td>{{money(r.amount)}}</td><td>{{r.outcome}}</td></tr></tbody></table></section>
   <p>Đóng bảng vẫn chạy. Bấm Dừng Auto để dừng; tải lại trang sẽ dừng tool. Một cược Stake đã nhận có thể vẫn kết thúc sau khi bấm dừng. Kiểm tra trạng thái trên trang nếu tool báo không xác nhận được dừng.</p>
  </template>
  <template v-else-if="tab==='Thống kê'">
   <div class="row section-title"><h2>Slide Statistics</h2><button v-if="embedded" @click="wide">Mở rộng / thu gọn ↔</button></div>
   <section><div class="row"><label>Cửa sổ dữ liệu<select v-model.number="statWindow"><option :value="0">Toàn bộ phiên</option><option :value="100">100 vòng</option><option :value="500">500 vòng</option><option :value="1000">1.000 vòng</option></select></label><span class="badge">{{statRounds.length}} vòng · dữ liệu DOM</span></div><p class="fine">Giữ tối đa 5.000 vòng trong phiên. GAP đếm số vòng không đạt mốc giữa hai hit. Chưa có hit: Current Gap là cận dưới ≥. Avg / Max chỉ dùng khoảng đã hoàn tất; không dự báo kết quả.</p></section>
   <h2>Min Win · Multi-Threshold Matrix</h2><section><div class="row"><label>Thêm ngưỡng ×<input type="number" min="1" v-model.number="newThreshold"></label><button @click="addThreshold">＋ Thêm</button></div><div class="table-scroll"><table class="gap-table"><thead><tr><th>Ngưỡng</th><th v-for="m in matrix">≥x{{m.threshold}} <button class="icon danger" @click="thresholds=thresholds.filter(t=>t!==m.threshold)" aria-label="Xóa ngưỡng">×</button></th></tr></thead><tbody><tr><th>Hits</th><td v-for="m in matrix">{{m.hits}}</td></tr><tr><th>Current Gap</th><td v-for="m in matrix">{{m.censored?'≥':''}}{{m.current}}</td></tr><tr><th>Avg Gap</th><td v-for="m in matrix">{{m.average===null?'—':m.average.toFixed(1)}}</td></tr><tr><th>Max Gap</th><td v-for="m in matrix">{{m.max??'—'}}</td></tr><tr><th>Ratio</th><td v-for="m in matrix" :class="m.ratio!==null&&m.ratio>=2?'negative':''">{{m.ratio===null?'—':m.ratio.toFixed(2)+'×'}}</td></tr></tbody></table></div></section>
   <h2>Multiplier Strip · 300 vòng mới nhất</h2><section><div class="strip"><span v-for="r in statRounds.slice(-300).reverse()" :style="{background:stripColor(r.value)}" :class="{big:r.value>=90}" :title="r.id">{{r.value}}×</span></div><p class="fine">Mới nhất ở đầu · viền vàng: ≥90×. Màu theo các mốc 3 / 6 / 10 / 24 / 45 / 88 / 250 / 460×.</p></section>
   <h2>Big Hits</h2><section><label>Ngưỡng hiển thị ×<input type="number" min="1" v-model.number="minHit"></label><div class="table-scroll"><table><thead><tr><th>Kết quả</th><th>Thời điểm đọc</th><th>ID vòng</th></tr></thead><tbody><tr v-for="r in bigHits"><td class="positive">{{r.value}}×</td><td>{{new Date(r.time).toLocaleTimeString('vi-VN')}}</td><td class="round-id" :title="r.id">{{r.id}}</td></tr></tbody></table><p v-if="!bigHits.length">Chưa có hit trong cửa sổ dữ liệu.</p></div></section>
   <h2>Thống kê chiến thuật</h2><section><label>Nguồn số liệu<select v-model="statsSource"><option>Auto</option><option>Mô phỏng</option></select></label><p v-if="!sessionStats">Chưa có phiên {{statsSource}}. Không sử dụng số liệu mô phỏng thay cho cược thật.</p><div class="metrics"><div><label>Thắng / thua</label><b>{{sessionStats?.wins||0}} / {{sessionStats?.losses||0}}</b></div><div><label>Tổng tiền đặt</label><b>{{money(sessionStats?.turnover||0)}}</b></div><div><label>Drawdown</label><b>{{money(sessionStats?.drawdown||0)}}</b></div></div><div class="table-scroll"><table><thead><tr><th>Bảng ×</th><th>Thắng</th><th>Thua</th><th>Chuỗi thua max</th><th>Lãi/lỗ tính</th></tr></thead><tbody><tr v-for="t in sessionTargets"><td>{{t.target}}</td><td>{{sessionStats?.byTarget?.[t.id]?.wins||0}}</td><td>{{sessionStats?.byTarget?.[t.id]?.losses||0}}</td><td>{{sessionStats?.byTarget?.[t.id]?.maxLossStreak||0}}</td><td>{{money(sessionStats?.byTarget?.[t.id]?.profit||0)}}</td></tr></tbody></table></div><p class="fine">Không có dữ liệu người chơi, whale hoặc tổng cược toàn sàn trong nguồn DOM này.</p></section>
   <h2>Recent Rounds</h2><section class="table-scroll"><table><thead><tr><th>Hệ số</th><th>Thời điểm đọc</th><th>ID</th></tr></thead><tbody><tr v-for="r in statRounds.slice(-100).reverse()"><td>{{r.value}}×</td><td>{{new Date(r.time).toLocaleTimeString('vi-VN')}}</td><td class="round-id" :title="r.id">{{r.id}}</td></tr></tbody></table></section>
  </template>
  <template v-else-if="tab==='Lịch sử'">
   <div class="row section-title"><h2>Vòng quan sát ({{ rounds.length }})</h2><button @click="useObserved" :disabled="!rounds.length">Dùng backtest</button></div>
   <section><div class="chips"><span v-for="r in rounds.slice(-60).reverse()" :class="{high:r.value>=5}">{{ r.value }}×</span></div><p class="fine">Mới nhất ở đầu. Tự lưu tối đa 5.000 vòng trong extension, giữ lại khi mở lại.</p><button @click="download('slide-rounds.json',JSON.stringify(rounds,null,2))">Xuất vòng JSON</button></section>
   <div class="row section-title"><h2>Lệnh mô phỏng gần nhất</h2><button @click="csv">Xuất CSV</button></div><section class="table-scroll"><table><thead><tr><th>Kết quả</th><th>Target</th><th>Bậc</th><th>Mức</th><th>Lãi/lỗ</th></tr></thead><tbody><tr v-for="r in logs"><td :title="r.roundId" :class="r.outcome==='WIN'?'positive':r.outcome==='LOSS'?'negative':''">{{ r.result }}×<small>{{ r.outcome }}</small></td><td>{{ r.target }}×</td><td>{{ r.step }}</td><td>{{ money(r.amount) }}</td><td>{{ money(r.profit) }}</td></tr></tbody></table><p v-if="!logs.length">Chưa có lệnh mô phỏng.</p></section>
  </template>
  <template v-else-if="tab==='Mô phỏng'"><section><h2>Mô phỏng · không đặt cược trên Stake</h2><p>Vốn khởi tạo {{money(config.bankroll)}} do bạn nhập, không phải ví Stake. Thắng/thua tại đây là phép tính giả lập trên vòng đã công bố.</p><button @click="tab='Cược'">Chỉnh chiến thuật</button><div v-for="p in next" class="plan"><b>{{p.target}}×</b><span>Bậc {{p.step}}</span><strong>{{p.action==='WAIT'?'CHỜ':money(p.amount)}}</strong></div></section></template>
  <template v-else-if="tab==='Backtest'">
   <h2>Chạy lại trên dữ liệu lịch sử</h2><section><p>Dữ liệu từ cũ → mới. Mỗi dòng một hệ số (1.45 hoặc 1,45), hoặc mảng JSON số / vòng đã xuất.</p><textarea v-model="backtext" rows="8" aria-label="Dữ liệu backtest"></textarea><div class="row"><label class="file-button">Nhập file<input type="file" accept=".json,.csv,.txt" @change="importHistory"></label><button @click="useObserved" :disabled="!rounds.length">Dùng vòng quan sát</button><button class="accent" @click="backtest">Chạy backtest</button></div></section>
   <section v-if="report"><div class="metrics"><div><label>Lãi / lỗ</label><b :class="report.profit<0?'negative':'positive'">{{ money(report.profit) }}</b></div><div><label>Drawdown tối đa</label><b>{{ money(report.drawdown) }}</b></div><div><label>Vòng xử lý</label><b>{{ report.count }}</b></div></div><svg viewBox="0 0 600 115" aria-label="Biểu đồ lãi lỗ mô phỏng"><polyline :points="spark" fill="none" stroke="#7bdae0" stroke-width="2"/></svg><p>{{ report.wins }} thắng · {{ report.losses }} thua · Tổng mức mô phỏng {{ money(report.turnover) }}</p><p>{{ report.halted||'Đã xử lý hết dữ liệu' }}</p><p class="fine">Biểu đồ và xuất lệnh giữ tối đa 10.000 lệnh cuối. Thống kê tính toàn bộ vòng đã xử lý. Drawdown tính theo vốn cuối mỗi vòng.</p></section>
  </template>
  <template v-else-if="tab==='Telegram'">
   <div class="row section-title"><h2>Tín hiệu / Telegram</h2><button @click="openSignals" :disabled="!hasExtension">Mở trang riêng ↗</button></div>
   <section><label class="check"><input type="checkbox" v-model="telegram.enabled"> Bật gửi Telegram</label><label>Bot Token<input type="password" v-model="telegram.token" autocomplete="off" placeholder="Nhập token của bot"></label><label>Chat ID<input v-model="telegram.chatId" autocomplete="off" placeholder="-100… hoặc @ten_kenh"></label><p class="fine">Bot phải có quyền gửi tin vào chat/nhóm/kênh này. Tạo bot qua @BotFather; với chat riêng, nhắn /start cho bot trước.</p><div class="grid2"><label class="check" v-for="(label,key) in eventLabels"><input type="checkbox" v-model="telegram.notify[key]"> {{label}}</label></div><div class="row"><button class="accent" @click="saveTelegram">Lưu Telegram</button><button @click="testTelegram" :disabled="!hasExtension">Gửi tin thử</button></div><p class="fine">Tin thử dùng cấu hình đã lưu. Token giữ trong extension, không nằm trong file cấu hình chiến thuật hoặc file xuất.</p></section>
   <section><h3>TÍN HIỆU THEO VÒNG QUAN SÁT</h3><label>Mốc Big Hit (cách nhau bằng dấu ;)<input v-model="signalTargets" placeholder="90;250;450"></label><label class="check"><input type="checkbox" v-model="telegram.rules.entry.enabled"> Báo khi vừa đủ chuỗi</label><div class="grid3"><label>Số vòng<input type="number" min="1" step="1" v-model.number="telegram.rules.entry.count"></label><label>Điều kiện<select v-model="telegram.rules.entry.op"><option>&lt;</option><option>&gt;</option><option>&lt;=</option><option>&gt;=</option></select></label><label>Mốc ×<input type="number" min="1" step="0.01" v-model.number="telegram.rules.entry.value"></label></div><p class="fine">Tín hiệu quan sát vẫn hoạt động khi Auto chưa chạy, miễn trang Slide còn mở. “Đủ chuỗi” chỉ báo khi chuyển từ chưa đủ sang đủ; không lặp mỗi vòng tiếp theo.</p><button class="accent wide" @click="saveTelegram">Lưu quy tắc tín hiệu</button></section>
   <section><h3>MẪU TIN NGẮN</h3><pre>💰 [STAKE] R123 · x2.26 · vốn~32.31
• 90: 1/6 - 12/360v
• 450: 1/6 - 12/438v</pre><p class="fine">R là số thứ tự tool quan sát trong phiên trang, không phải số vòng chính thức của Stake. Vốn~ là số liệu tool tính. Tin thắng, tăng bậc và Big Hit được gửi riêng.</p></section>
   <div class="row section-title"><h2>Lịch sử tín hiệu ({{signalLogs.length}})</h2><button @click="download('slide-signals.json',JSON.stringify(signalLogs,null,2))">Xuất JSON</button></div>
   <section><p v-if="!signalLogs.length">Chưa có tín hiệu. Mở trang Slide để bắt đầu quan sát.</p><article class="signal" v-for="s in signalLogs.slice(-100).reverse()"><div class="row"><span class="badge">{{s.kind}}</span><small>{{new Date(s.time).toLocaleTimeString('vi-VN')}}</small></div><pre>{{s.text}}</pre><small>{{s.status}}</small></article><p class="fine">Lưu tối đa 500 tin; hiển thị 100 tin mới nhất. Mất mạng/timeout sẽ ghi lỗi và không tự gửi lại để tránh trùng.</p></section>
  </template>
  <template v-else>
   <section><h2>Cài và sử dụng</h2><ol><li>Giải nén, mở chrome://extensions, bật Chế độ nhà phát triển.</li><li>Chọn Load unpacked / Tải tiện ích đã giải nén, chọn thư mục dist.</li><li>Mở stake1022.com/vi/casino/games/slide và bấm biểu tượng Slide Lab.</li><li>Ở màn hình Cược: chọn số dư, chỉnh target/bậc, kiểm tra giới hạn rồi bấm Bắt đầu cược thật.</li><li>Khi nguồn dữ liệu gián đoạn, phiên sẽ dừng. Bắt đầu lại tạo phiên mới.</li></ol><h3>Cách tính</h3><p>Vòng ≥ target: lợi nhuận = mức × (target − 1). Vòng &lt; target: lỗ = mức. Điều kiện vào chuỗi chỉ xét vòng trước đó.</p><p>Nhiều target dùng chung vốn; mỗi target có bậc độc lập. Không đủ vốn cho tổng mức của một vòng → dừng cả phiên.</p><p>Đây là paper betting trên dữ liệu đã công bố, không xác minh thời điểm đặt cược thực tế. Lịch sử kết quả không dự báo được vòng tiếp theo.</p><h3>Phạm vi v1</h3><p>Theo dõi DOM, mô phỏng, backtest và lưu cấu hình cục bộ. Auto Bet điều khiển DOM của Stake, xóa/thêm dòng cược khi đổi bậc. Chạy ở content script nên đóng bảng vẫn chạy Auto; tải lại trang không tự khởi động lại. Khi bật Telegram, gửi tín hiệu tới chat bạn cấu hình qua API chính thức của Telegram.</p><p class="fine">Selector lịch sử đã được kiểm tra trên trang ngày 07/10/2026. Nếu Stake thay DOM, sửa src/adapter.ts rồi build lại.</p></section>
  </template>
  
 </main>
</template>
